"""Generate the audit backlog and LaTeX appendix from one reviewed data source.

Run from this directory with Python 3. Compile main.tex separately.
The generator checks every source locator against the repository.
"""
from pathlib import Path
import collections
import csv
import hashlib
import json
import textwrap

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
FINDINGS = []

def group(category, rows):
    for row in rows.strip().splitlines():
        severity, kind, title, location, behavior, fix, acceptance = row.split(" | ")
        path, line = location.rsplit(":", 1)
        source = ROOT / path
        lines = source.read_text().splitlines()
        assert 0 < int(line) <= len(lines), location
        FINDINGS.append(dict(id=f"CQ-{len(FINDINGS)+1:03}", category=category,
            severity=severity, kind=kind, title=title, location=location,
            evidence="Source review", behavior=behavior, fix=fix,
            acceptance=acceptance, source_line=lines[int(line)-1].strip(),
            source_sha256=hashlib.sha256(source.read_bytes()).hexdigest()))

