# Mark only executed behavior as reproduced. Other findings remain source-reviewed.
PROBES = {
    "Setting a rate limit to zero panics":"zero_rate_limit_panic",
    "Negative security settings silently disable protection":"negative_rate_limit_configuration",
    "Registration counts name bytes while profile editing counts characters":"registration_name_byte_limit",
    "Sensitive API responses omit explicit no-store policy":"sensitive_response_cache_control",
    "A single malformed availability boundary is accepted":"single_invalid_availability_boundary",
    "Noncanonical question keys validate but grade incorrectly":"noncanonical_question_index",
    "Invalid answer payloads look like service outages":"invalid_answer_status",
    "A timed assessment accepts submission without a started attempt":"timed_submission_without_start",
    "Teachers can enter the learner submission pipeline":"teacher_submission",
    "Editing duration changes deadlines for attempts already running":"running_deadline_changes",
    "Close does not stop an assessment that allows late work":"close_still_accepts_late_work",
    "Autosave deduplication does not bind the answer snapshot":"autosave_request_payload_mismatch",
    "Board history and export URLs do not match the API":"frontend_board_history_route",
    "Any signed-in learner can read a known room's history":"unrelated_learner_board_export",
    "Any teacher can restore any known board":"unrelated_teacher_board_restore",
    "Restore returns capitalized element fields that the client does not read":"unrelated_teacher_board_restore",
}
for f in FINDINGS:
    if f['title'] in PROBES:
        f['evidence'] = 'Reproduced (isolated memory API)'
        f['probe'] = PROBES[f['title']]
    if f['title'] == 'Select triggers display internal values instead of labels':
        f['evidence'] = 'Observed in browser and source'
    if f['title'] == 'Authentication tests expire against the real calendar':
        f['evidence'] = 'Reproduced (existing Go test suite)'

assert len(FINDINGS) == 120, len(FINDINGS)
(HERE/'findings.json').write_text(json.dumps(FINDINGS,indent=2)+'\n')
with (HERE/'findings.csv').open('w',newline='') as out:
    fields=['id','severity','kind','category','title','evidence','location','behavior','fix','acceptance']
    writer=csv.DictWriter(out,fieldnames=fields,extrasaction='ignore',lineterminator='\n')
    writer.writeheader();writer.writerows(FINDINGS)

md=['# Continuum quality backlog','',
    'Baseline: `1ec26fb0b59cb4704ccce28b93fc4046da5a35f4` · 23 October 2026.',
    '', '120 distinct items. Defects, risks, policy decisions and polish are labeled separately. Source review is not a claim of runtime reproduction. The full project context and verification results are in the LaTeX report.', '']
for f in FINDINGS:
    md += [f"## {f['id']} · {f['title']}", '', f"**{f['severity']} · {f['kind']} · {f['evidence']}**",'',
        f"Source: [{f['location']}](../../../{f['location']})", '', f['behavior'], '',
        '**Fix:** '+f['fix'], '', '**Acceptance:** '+f['acceptance'], '']
(HERE/'BACKLOG.md').write_text('\n'.join(md))

def tex(value):
    return ''.join({'\\':r'\textbackslash{}','&':r'\&','%':r'\%','$':r'\$','#':r'\#','_':r'\_','{':r'\{','}':r'\}','~':r'\textasciitilde{}','^':r'\textasciicircum{}'}.get(c,c) for c in str(value))

counts=collections.Counter(f['severity'] for f in FINDINGS)
category_counts=collections.Counter(f['category'] for f in FINDINGS)
kind_counts=collections.Counter(f['kind'] for f in FINDINGS)
summary={'total':len(FINDINGS),'severity':dict(counts),'categories':dict(category_counts),
    'kinds':dict(kind_counts),'evidence':dict(collections.Counter(f['evidence'] for f in FINDINGS))}
(HERE/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')

# Four findings per page keeps entries intact and avoids excessive white space.
appendix=[]
seen_categories=set()
for start in range(0,len(FINDINGS),4):
        items=FINDINGS[start:start+4]
        appendix += [r'\clearpage',r'\section*{Issue register: '+items[0]['id']+' to '+items[-1]['id']+'}']
        for f in items:
            if f['category'] not in seen_categories:
                appendix += [r'\phantomsection\addcontentsline{toc}{subsection}{'+tex(f['category'])+'}']
                seen_categories.add(f['category'])
            appendix += [r'\begin{finding}{'+f['id']+'}{'+f['severity']+'}{'+tex(f['title'])+'}',
                r'\textbf{'+tex(f['kind'])+r'} $\cdot$ '+tex(f['evidence'])+r'\par',
                r'\textbf{Source}\quad\path{'+f['location']+r'}\par',
                tex(f['behavior'])+r'\par',
                r'\textbf{Fix.} '+tex(f['fix'])+r'\par',
                r'\textbf{Accept when.} '+tex(f['acceptance']),r'\end{finding}']
(HERE/'findings.tex').write_text('\n'.join(appendix)+'\n')

severity_rows='\n'.join(tex(k)+' & '+str(v)+r' \\' for k,v in sorted(counts.items()))
category_rows='\n'.join(tex(k)+' & '+str(v)+r' \\' for k,v in category_counts.items())
(HERE/'summary-tables.tex').write_text(r'\begin{tabularx}{\textwidth}{Xr}\toprule Category & Items \\\midrule'+'\n'+category_rows+r'\bottomrule\end{tabularx}'+'\n')
print(json.dumps(summary,indent=2))
